export const ENEMY_MARKER_COLOR='#ff343e';
export function enemyMarkers(state,region=state.region){if(region!==state.region)return [];return state.enemies.filter(e=>e.hp>0).map(e=>({id:e.id,x:e.x,z:e.z,boss:e.isBoss,color:ENEMY_MARKER_COLOR,size:e.isBoss?7:5}));}
export function paintEnemyMarkers(ctx,state,project,region=state.region){for(const marker of enemyMarkers(state,region)){const [x,y]=project(marker.x,marker.z);ctx.fillStyle='#361523';ctx.fillRect(Math.round(x)-marker.size/2-1,Math.round(y)-marker.size/2-1,marker.size+2,marker.size+2);ctx.fillStyle=marker.color;ctx.fillRect(Math.round(x)-Math.floor(marker.size/2),Math.round(y)-Math.floor(marker.size/2),marker.size,marker.size);if(marker.boss){ctx.strokeStyle='#ffb0a8';ctx.lineWidth=1;ctx.strokeRect(Math.round(x)-5,Math.round(y)-5,10,10);}}}
